class Solution {
    int find(vector<int>& parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
public:
    int maxNumEdgesToRemove(int n, vector<vector<int>>& edges) {
        vector<int> parentA(n + 1), parentB(n + 1);
        vector<int> rankA(n + 1, 0), rankB(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            parentA[i] = i;
            parentB[i] = i;
        }

        int componentsA = n, componentsB = n;
        int removed = 0;

        // Pass 1: type 3 edges (shared by Alice and Bob)
        for (auto& e : edges) {
            if (e[0] != 3) continue;
            int ra = find(parentA, e[1]);
            int rb = find(parentA, e[2]);
            int rc = find(parentB, e[1]);
            int rd = find(parentB, e[2]);
            if (ra == rb && rc == rd) {
                removed++;
            } else {
                if (ra != rb) {
                    if (rankA[ra] < rankA[rb]) swap(ra, rb);
                    parentA[rb] = ra;
                    if (rankA[ra] == rankA[rb]) rankA[ra]++;
                    componentsA--;
                }
                if (rc != rd) {
                    if (rankB[rc] < rankB[rd]) swap(rc, rd);
                    parentB[rd] = rc;
                    if (rankB[rc] == rankB[rd]) rankB[rc]++;
                    componentsB--;
                }
            }
        }

        // Pass 2: type 1 edges (Alice only)
        for (auto& e : edges) {
            if (e[0] != 1) continue;
            int ra = find(parentA, e[1]);
            int rb = find(parentA, e[2]);
            if (ra == rb) {
                removed++;
            } else {
                if (rankA[ra] < rankA[rb]) swap(ra, rb);
                parentA[rb] = ra;
                if (rankA[ra] == rankA[rb]) rankA[ra]++;
                componentsA--;
            }
        }

        // Pass 3: type 2 edges (Bob only)
        for (auto& e : edges) {
            if (e[0] != 2) continue;
            int ra = find(parentB, e[1]);
            int rb = find(parentB, e[2]);
            if (ra == rb) {
                removed++;
            } else {
                if (rankB[ra] < rankB[rb]) swap(ra, rb);
                parentB[rb] = ra;
                if (rankB[ra] == rankB[rb]) rankB[ra]++;
                componentsB--;
            }
        }

        if (componentsA != 1 || componentsB != 1) return -1;
        return removed;
    }
};
